{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <meta name="description" content="A modern approach to immersive sound gatherings in {{CITY}}, {{STATE}}">
  <style>
    :root{--bg:#0f0f10;--card:#0f1720;--muted:#a8b0b8;--accent:#9cc7c7;--glass:rgba(255,255,255,0.04);--cta:#cbeef0}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:#e6f6f6;background:linear-gradient(180deg,#061012 0%, #07151a 45%, #0b1112 100%);min-height:100vh;display:flex;flex-direction:column}
    header{display:flex;align-items:center;justify-content:space-between;padding:28px 36px;background:linear-gradient(90deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#7aaeb3);display:grid;place-items:center;font-weight:700;color:#052425}
    nav{display:flex;gap:18px}
    nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:6px;font-weight:600}
    nav a[href$="about.html"]{color:var(--cta)}
    .hero{display:grid;grid-template-columns:1fr 420px;gap:28px;padding:48px 36px;align-items:center}
    .poster{padding:36px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);box-shadow:0 6px 30px rgba(3,15,16,0.6);position:relative;overflow:hidden}
    .poster h1{margin:0;font-size:34px;letter-spacing:-0.6px}
    .poster p{color:var(--muted);margin-top:12px;line-height:1.5}
    .poster .cta{display:inline-block;margin-top:18px;padding:12px 16px;border-radius:10px;background:var(--cta);color:#052425;font-weight:700;text-decoration:none}
    .panel{padding:18px;border-radius:12px;background:var(--glass);border:1px solid rgba(255,255,255,0.03)}

    /* Decorative svg-block */
    .pattern-wrap{position:absolute;right:-40px;top:-30px;opacity:0.08;transform:rotate(-12deg)}

    .pills{display:flex;gap:12px;flex-wrap:wrap;margin-top:16px}
    .pill{background:rgba(255,255,255,0.02);padding:10px 12px;border-radius:10px;font-weight:600;color:var(--muted)}

    .pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding:36px}
    .pillar{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px}
    .pillar h3{margin:0 0 8px 0}
    .pillar p{margin:0;color:var(--muted)}

    /* Proof gallery */
    .proof{display:flex;gap:18px;align-items:flex-start;padding:36px}
    .testimonials{flex:1;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:18px;border-radius:10px}
    .testimonials blockquote{margin:0;padding:12px;color:var(--muted);font-style:italic}
    .badges{width:220px;display:flex;flex-direction:column;gap:12px}
    .badge{background:rgba(255,255,255,0.03);padding:12px;border-radius:8px;display:flex;gap:12px;align-items:center;cursor:help}
    .badge .icon{width:36px;height:36px;border-radius:6px;background:linear-gradient(135deg,#dbeff0,#9cc7c7);display:grid;place-items:center;color:#052425;font-weight:800}
    .tooltip{position:fixed;background:#021213;color:#aeecee;padding:8px 12px;border-radius:8px;font-size:13px;pointer-events:none;opacity:0;transform:translateY(-6px);transition:opacity .18s,transform .18s}

    footer{margin-top:auto;padding:22px 36px;color:var(--muted);display:flex;align-items:center;justify-content:space-between}

    @media (max-width:900px){.hero{grid-template-columns:1fr;}.pillars{grid-template-columns:1fr}.badges{width:100%}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Offerings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">About</a>
      <a href="faq.html">Q&amp;A</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="poster">
        <div class="pattern-wrap">
          <!-- Inline SVG pattern: unique geometry -->
          <svg width="240" height="240" viewBox="0 0 240 240" xmlns="http://www.w3.org/2000/svg">
            <defs>
              <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#9cc7c7" stop-opacity="0.9"/><stop offset="1" stop-color="#6aa7a7" stop-opacity="0.6"/></linearGradient>
            </defs>
            <g fill="none" stroke="url(#g1)" stroke-width="1.6">
              <path d="M10 120 C40 20, 200 20, 230 120"/>
              <path d="M10 140 C40 240, 200 240, 230 140" opacity="0.6"/>
              <circle cx="120" cy="120" r="52" opacity="0.04" fill="#9cc7c7"/>
            </g>
          </svg>
        </div>
        <h1>We craft focused sound gatherings to steady attention and reveal calm.</h1>
        <p>We run concentrated sound immersions that anchor the nervous system, using tuned instruments and held intention. Sessions are organized as compact, intentional expeditions — excellent for those who want clarity through quiet, and for people looking to depart from usual rest rituals.</p>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <div class="pills">
          <div class="pill">Small groups • 40–60 min</div>
          <div class="pill">Hybrid booking available</div>
          <div class="pill">Suitable for newcomers</div>
        </div>
      </div>

      <aside class="panel">
        <h3>Quick facts</h3>
        <p style="color:var(--muted);margin-top:8px">We host gatherings in {{CITY}}, {{STATE}}. Drop-ins welcome, and we prioritize focused cohorts for deeper immersion.</p>
        <div style="margin-top:12px">
          <div style="font-size:13px;color:var(--muted)">Contact</div>
          <div style="margin-top:6px;font-weight:700">{{PHONE}} · <a href="mailto:{{EMAIL}}" style="color:var(--cta);text-decoration:none">{{EMAIL}}</a></div>
        </div>
      </aside>
    </section>

    <section class="pillars">
      <div class="pillar">
        <h3>Design</h3>
        <p>Each sequence is hand-arranged: waves of tone, pockets for breath, and intentional silences to let impressions settle. Instruments are tuned to support the nervous system, not to impress.</p>
      </div>
      <div class="pillar">
        <h3>Containment</h3>
        <p>We hold a steady frame so that people can go inward without navigating logistics. The facilitator cues arrival, transition, and return for a safe arc.</p>
      </div>
      <div class="pillar">
        <h3>Aftercare</h3>
        <p>Short integration time follows every immersion — simple prompts and gentle conversation help integrate whatever shifts occurred during the session.</p>
      </div>
    </section>

    <section class="proof">
      <div class="testimonials panel">
        <h4 style="margin-top:0">Proof & stories</h4>
        <blockquote id="quote">“A precise container that helped me rest in a way I didn’t expect — focused and quiet.” — J. Morales</blockquote>
        <div style="margin-top:14px;color:var(--muted);font-size:14px">Rotation of voices below — credibility badges at right.</div>
      </div>

      <div class="badges panel">
        <div class="badge" data-tip="Recommended by the Regional Wellness Collective">
          <div class="icon">W</div>
          <div>
            <div style="font-weight:700">Wellness Collective</div>
            <div style="font-size:13px;color:var(--muted)">Regional endorsement</div>
          </div>
        </div>

        <div class="badge" data-tip="Practitioner-reviewed protocols for safer sessions">
          <div class="icon">P</div>
          <div>
            <div style="font-weight:700">Practitioners Guild</div>
            <div style="font-size:13px;color:var(--muted)">Peer-reviewed</div>
          </div>
        </div>

        <div class="badge" data-tip="Featured in local press for community impact">
          <div class="icon">L</div>
          <div>
            <div style="font-weight:700">Local Press</div>
            <div style="font-size:13px;color:var(--muted)">Community story</div>
          </div>
        </div>
      </div>
    </section>

    <section style="padding:36px">
      <div class="panel">
        <h4 style="margin-top:0">Contraindications & safety</h4>
        <p style="color:var(--muted)">Sound immersions are generally gentle but may not be suitable for everyone. If you have epilepsy, are pregnant and have specific medical guidance, have implanted medical devices, are in acute psychiatric crisis, or experience sensitivity to strong vibrations, consult your healthcare provider before attending. If you are taking medication that affects alertness, or have a history of dissociation, please contact us before booking. We prioritize clear communication and can adapt elements where possible.</p>
      </div>
    </section>
  </main>

  <footer>
    <div>© <span id="year"></span> {{BUSINESS_NAME}}</div>
    <div style="color:var(--muted)">Located in {{CITY}}, {{STATE}} · <a href="mailto:{{EMAIL}}" style="color:var(--cta);text-decoration:none">{{EMAIL}}</a></div>
  </footer>

  <div class="tooltip" id="tooltip"></div>

  <script>
    // rotate testimonials
    (function(){
      const quotes = [
        '"A precise container that helped me rest in a way I didn\'t expect — focused and quiet." — J. Morales',
        '"I left with a clearer sense of boundaries and a calmer rhythm to sleep." — S. Ng',
        '"Not what I expected — a direct, quietly powerful hour." — R. Patel'
      ];
      let i=0;const el=document.getElementById('quote');
      setInterval(()=>{i=(i+1)%quotes.length;el.textContent=quotes[i];},4500);
    })();

    // badge tooltips
    (function(){
      const tip = document.getElementById('tooltip');
      document.querySelectorAll('.badge').forEach(b=>{
        b.addEventListener('mousemove',e=>{
          const t = b.getAttribute('data-tip');
          tip.textContent = t;
          tip.style.left = (e.clientX + 12) + 'px';
          tip.style.top = (e.clientY + 10) + 'px';
          tip.style.opacity = 1;
          tip.style.transform = 'translateY(0)';
        });
        b.addEventListener('mouseleave',()=>{tip.style.opacity=0;});
      });
    })();

    // footer year
    document.getElementById('year').textContent = new Date().getFullYear();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Q&amp;A — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Common questions about immersive sound experiences in {{CITY}}, {{STATE}}">
  <style>
    :root{--bg:#071519;--muted:#b7cfcf;--card:#0f2122;--accent:#8fc9c9;--cta:#cbeef0}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;color:#eaf7f6;background:linear-gradient(180deg,#041213 0%, #06171a 100%)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:rgba(255,255,255,0.02)}
    .logo{width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,#9bd2d2,#7aaeb3);display:grid;place-items:center;font-weight:700;color:#052425}
    nav{display:flex;gap:14px}
    nav a{color:var(--muted);text-decoration:none;padding:6px 10px;border-radius:6px}
    nav a[href$="faq.html"]{color:var(--cta)}
    main{padding:26px;max-width:980px;margin:0 auto}
    .lead{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:22px;border-radius:12px}
    h1{margin:0 0 8px 0}
    .group{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .q{background:#072022;padding:16px;border-radius:10px;margin-bottom:8px}
    .q h3{margin:0;font-size:16px}
    .q p{margin:8px 0 0 0;color:var(--muted)}
    .aside{padding:16px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)}
    .m-v-t{margin-top:18px}
    .myth{background:#072a2b;padding:12px;border-radius:8px;margin-bottom:10px}
    .truth{background:#0b2b28;padding:12px;border-radius:8px}
    .proof-small{display:flex;gap:10px;align-items:center;margin-top:12px}
    .avatar{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#cfeff0,#89c5c5);display:grid;place-items:center;color:#032223;font-weight:700}
    .book-cta{display:inline-block;padding:10px 14px;border-radius:10px;background:var(--cta);color:#042424;font-weight:700;text-decoration:none}
    .disclaimer{font-size:13px;color:#b6d6d6;margin-top:12px}
    footer{padding:18px 28px;color:var(--muted);display:flex;justify-content:space-between}
    @media (max-width:900px){.group{grid-template-columns:1fr} .aside{order:2}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Offerings</a>
      <a href="about.html">About</a>
      <a href="faq.html">Q&amp;A</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <section class="lead">
      <h1>Questions & clarifications</h1>
      <p style="color:var(--muted)">Below you’ll find pragmatic answers for attending, preparing, and deciding if an immersive sound meeting is right for you.</p>
    </section>

    <section class="group">
      <div>
        <div class="q">
          <h3>What should I wear?</h3>
          <p>Comfortable layers and something you can lie or sit in for an extended period. Mats and blankets are available; bring what helps you rest.</p>
        </div>

        <div class="q">
          <h3>Can I move or fall asleep?</h3>
          <p>Movement is allowed; long periods of sleep can reduce the integration benefit. Facilitators will guide a gentle return if you drift.</p>
        </div>

        <div class="q">
          <h3>How long is a session?</h3>
          <p>Our group cycles are typically 45–60 minutes, with a short integration window afterwards.</p>
        </div>

        <div class="q">
          <h3>Is this therapy?</h3>
          <p>These offerings are experiential and supportive but are not a substitute for clinical therapy. If you are in active therapy, consider coordinating with your clinician.</p>
        </div>

        <div class="q">
          <h3>Are sessions safe for everyone?</h3>
          <p>Most people find them gentle. Contraindications include epilepsy, recent head injury, certain cardiac devices, and acute psychiatric states. Contact us for adaptations.</p>
        </div>

        <div class="q">
          <h3>Payment & cancellation</h3>
          <p>Details are listed on the Rates page. We offer sliding options for some intensive evenings — please contact us if finances are a constraint.</p>
        </div>
      </div>

      <aside class="aside">
        <div style="font-weight:700">Myth vs Truth</div>
        <div class="m-v-t">
          <div class="myth"><strong>Myth:</strong> Sound baths are always immersive sleep experiences.</div>
          <div class="truth"><strong>Truth:</strong> Our gatherings are crafted experiences with clear arcs designed for inward focus, not simply passive sleep.</div>
        </div>

        <div style="margin-top:14px;font-weight:700">A small proof gallery</div>
        <div class="proof-small">
          <div class="avatar">A</div>
          <div>
            <div style="font-weight:700">"Clearer sleep the next night"</div>
            <div style="color:var(--muted);font-size:13px">— A. Torres</div>
          </div>
        </div>

        <div style="margin-top:12px">
          <a class="book-cta" href="book.html">Select a session</a>
        </div>

        <div class="disclaimer">
          Contraindications: If you have a history of seizures, certain cardiac implants, or are under acute psychiatric care, please consult your physician prior to attending. We may be able to offer adapted formats.
        </div>
      </aside>
    </section>

    <section style="margin-top:22px;max-width:980px;margin-left:auto;margin-right:auto">
      <h3>More technical questions</h3>
      <div style="display:grid;gap:12px;margin-top:12px">
        <div class="q">
          <h3>Why instruments?</h3>
          <p>Acoustic overtones and low-frequency vibrations engage attention differently than spoken guidance. Our instruments are chosen for clarity and safety.</p>
        </div>
        <div class="q">
          <h3>Can I request a private evening?</h3>
          <p>Yes — we run private intensives tailored to small cohorts. See the Private sessions page for details.</p>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div>Questions? Call {{PHONE}}</div>
    <div style="color:var(--muted)"><a href="mailto:{{EMAIL}}" style="color:var(--cta);text-decoration:none">{{EMAIL}}</a></div>
  </footer>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Choose your sound intensity and book an immersive session in {{CITY}}, {{STATE}}">
  <style>
    :root{--bg:#041418;--muted:#bfe9e8;--card:#062425;--accent:#8fd6d6;--cta:#d4fbfb}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#021315 0%,#051d1d 100%);color:#e8fbfb}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 22px;background:rgba(255,255,255,0.02)}
    .logo{width:40px;height:40px;border-radius:8px;background:linear-gradient(135deg,#caf3f3,#7ecfcf);display:grid;place-items:center;color:#042425;font-weight:800}
    nav{display:flex;gap:12px}
    nav a{color:var(--muted);text-decoration:none}
    main{max-width:1060px;margin:22px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:18px;border-radius:12px}
    h1{margin:0 0 8px 0}
    .mixer{display:flex;gap:10px;align-items:center;margin-top:14px}
    .mixer button{flex:1;padding:10px;border-radius:10px;border:0;background:rgba(255,255,255,0.02);color:var(--muted);font-weight:700;cursor:pointer}
    .mixer button.active{background:linear-gradient(90deg,var(--accent),#6fbdbd);color:#012222}
    .programs{display:grid;gap:12px;margin-top:16px}
    .prog{padding:12px;border-radius:10px;background:rgba(255,255,255,0.02);display:flex;justify-content:space-between;align-items:center}
    .price{font-weight:800;color:var(--cta)}
    .bookform{display:flex;flex-direction:column;gap:10px}
    input,select{padding:10px;border-radius:8px;border:0;background:rgba(255,255,255,0.03);color:inherit}
    .reserve{padding:12px;border-radius:10px;border:0;background:var(--cta);color:#042425;font-weight:800;cursor:pointer}
    .small{font-size:13px;color:var(--muted)}
    .testimonials{margin-top:18px}
    .testimonials blockquote{margin:0;color:var(--muted);font-style:italic}
    .disclaimer{font-size:13px;color:#bfe9e8;margin-top:12px}
    footer{padding:18px;color:var(--muted);display:flex;justify-content:space-between}
    @media (max-width:980px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">SB</div>
      <div style="font-weight:700">{{BUSINESS_NAME}}</div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Offerings</a>
      <a href="about.html">About</a>
      <a href="faq.html">Q&amp;A</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <div>
        <div class="card">
          <h1>Reserve an immersion</h1>
          <p class="small">Choose a sound preference and see personalized program suggestions. We call the setting a 'preference' because the facilitator can adapt dynamics at the door.</p>

          <div class="mixer" role="tablist" aria-label="Sound preference">
            <button id="gentle" data-level="gentle">Gentle</button>
            <button id="medium" data-level="medium">Medium</button>
            <button id="intense" data-level="intense">Intense</button>
          </div>

          <div class="programs" id="programs">
            <!-- program cards injected here -->
          </div>

          <div style="margin-top:12px" class="small">Pricing shown below is illustrative; final options appear on confirmation.</div>

          <div class="disclaimer">If you have epilepsy, a cardiac implant, are pregnant with specific guidance, or are in acute psychiatric crisis, contact us before booking. We can discuss adaptations or alternatives.</div>
        </div>

        <div class="card testimonials">
          <h4 style="margin-top:0">What people notice</h4>
          <blockquote id="book-quote">"A tightly held hour that felt like a slow recalibration." — K. L.</blockquote>
        </div>
      </div>

      <aside>
        <div class="card">
          <h3>Reserve</h3>
          <form class="bookform" id="bookForm" onsubmit="return false;">
            <label class="small">Select session</label>
            <select id="sessionSelect">
              <option value="open-1">Next available — Open Group</option>
              <option value="intensive-1">Next intensive — Focus Cohort</option>
            </select>

            <label class="small">Your name</label>
            <input id="name" placeholder="Full name" required />
            <label class="small">Contact email</label>
            <input id="email" type="email" placeholder="you@domain.com" required />

            <div style="display:flex;gap:8px;align-items:center;margin-top:6px">
              <button class="reserve" id="confirm">{{PRIMARY_CTA_LABEL}}</button>
            </div>

            <div class="small" style="margin-top:8px">After you tap reserve, we'll confirm details and finalize payment on the booking page.</div>
          </form>
        </div>

        <div class="card" style="margin-top:12px">
          <h4 style="margin-top:0">Next events</h4>
          <ul style="color:var(--muted);padding-left:18px">
            <li><strong>Feb 26</strong> — Evening Focus Cohort</li>
            <li><strong>Mar 5</strong> — Open Group (drop-in)</li>
            <li><strong>Mar 18</strong> — Weekend Intensive</li>
          </ul>
          <div style="margin-top:8px"><a href="events.html" style="color:var(--accent);text-decoration:none">See full calendar</a></div>
        </div>
      </aside>
    </div>
  </main>

  <footer>
    <div>Questions? <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a></div>
    <div style="color:var(--muted)">{{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    // Programs for each intensity
    const catalog = {
      gentle: [
        {id:'g1',name:'Hearth Session — Gentle Drift',desc:'Low-tone cushions and short stretches, 40 minutes. Ideal for early evenings.',price:'$28'},
        {id:'g2',name:'Ease Practice — Soft Arc',desc:'A gentle arc for orbiting attention without heavy vibrations.',price:'$34'}
      ],
      medium: [
        {id:'m1',name:'Core Evening — Warm Density',desc:'Layered overtones and longer sustain, 50 minutes.',price:'$44'},
        {id:'m2',name:'Quiet Intensives — Mid-Arc',desc:'For those seeking a firmer structure with integration prompts.',price:'$58'}
      ],
      intense: [
        {id:'i1',name:'Focused Intensive — Deep Frame',desc:'Directed cohort work, deeper frequencies, 60+ minutes.',price:'$88'},
        {id:'i2',name:'Sonic Sculpt — Extended Cohort',desc:'Extended evening with solo support and integration, 90 minutes.',price:'$140'}
      ]
    };

    // initial state
    let state = localStorage.getItem('sb_pref') || 'medium';
