    const programsEl = document.getElementById('programs');
    const bookQuote = document.getElementById('book-quote');

    function renderPreference(pref){
      // activate button
      Object.keys(buttons).forEach(k=>buttons[k].classList.toggle('active',k===pref));
      // render programs
      programsEl.innerHTML='';
      catalog[pref].forEach(p=>{
        const div = document.createElement('div');div.className='prog';
        div.innerHTML = `<div><strong>${p.name}</strong><div style=\"color:var(--muted);font-size:13px;margin-top:6px;max-width:640px\">${p.desc}</div></div><div style=\"text-align:right\"><div class=\"price\">${p.price}</div><div style=\"font-size:12px;color:var(--muted);margin-top:6px\">Per person</div></div>`;
        programsEl.appendChild(div);
      });

      // update testimonial tone
      const notes = {
        gentle:'"A soft, clear landing for an evening." — M. R.',
        medium:'"A dependable structure that helped me unwind with clarity." — S. P.',
        intense:'"A potent container — gave me big shifts in focus." — N. K.'
      };
      bookQuote.textContent = notes[pref];
      localStorage.setItem('sb_pref',pref);
    }

    // attach event listeners
    Object.values(buttons).forEach(b=>b.addEventListener('click',()=>{renderPreference(b.getAttribute('data-level')); }));

    // initialize
    renderPreference(state);

    // simple form flow
    document.getElementById('confirm').addEventListener('click',async()=>{
      const name = document.getElementById('name').value.trim();
      const email = document.getElementById('email').value.trim();
      if(!name || !email){alert('Please provide name and email to continue.');return}
      // show pseudo confirmation
      const pref = localStorage.getItem('sb_pref') || 'medium';
      const selectedPrograms = catalog[pref].map(p=>p.name).join('\n- ');
      const msg = `Thanks ${name}.\n\nYou selected: ${pref.toUpperCase()} preference.\nSuggested programs:\n- ${selectedPrograms}\n\nWe will email ${email} with the next steps to finalize your booking.`;
      alert(msg);
      // pretend to navigate
      window.location.href = '{{PRIMARY_CTA_URL}}';
    });

    // also rotate a tiny testimonial in the programs area for motion
    (function(){
      const quotes = ['"A soft, clear landing for an evening." — M. R.','"A dependable structure that helped me unwind with clarity." — S. P.','"A potent container — gave me big shifts in focus." — N. K.'];
      let i=0;setInterval(()=>{i=(i+1)%quotes.length;document.querySelectorAll('.testimonials blockquote')[0].textContent=quotes[i];},4800);
    })();
  </script>
